    private static void AddCard(TableLayoutPanel layout, Label valueLabel, string caption, int col, int row, Color accent)
    {
        var card = new Panel { Dock = DockStyle.Fill, BackColor = Color.White, Margin = new Padding(5), Padding = new Padding(13) };
        var stripe = new Panel { BackColor = accent, Dock = DockStyle.Left, Width = 5 };
        valueLabel.Name = "metricValue" + col + row;
        valueLabel.Text = "0";
        valueLabel.Font = new Font("Segoe UI", 24F, FontStyle.Bold);
        valueLabel.ForeColor = accent;
        valueLabel.Location = new Point(23, 42);
        valueLabel.AutoSize = true;
        var titleLabel = new Label { Text = caption, ForeColor = Color.FromArgb(71, 85, 105), Font = new Font("Segoe UI", 9F, FontStyle.Bold), Location = new Point(23, 14), AutoSize = true };
        card.Controls.Add(valueLabel);
        card.Controls.Add(titleLabel);
        card.Controls.Add(stripe);
        layout.Controls.Add(card, col, row);
    }
